abhinav_4_5 = {
    'hi': '।।9.4--9.5।। श्री अभिनवगुप्त कहते हैं: सम्पूर्ण जगत् मेरे अव्यक्त स्वरूप से व्याप्त है, सब भूत मुझमें स्थित हैं किंतु मैं उनमें आश्रित रूप से स्थित नहीं हूँ; और न ही भूत मुझमें भौतिक रूप से स्थित हैं—यह मेरा ऐश्वर्य योग है, जो भूतों का धारण-पोषण करने वाला आत्मा है फिर भी भूतों में लिप्त नहीं होता।',
    'en': '9.4--9.5 Sri Abhinavagupta states: All this cosmos is pervaded by My unmanifest form; all beings abide in Me, but I am not dependent on them; nor do beings abide in Me physically—behold My divine mystery (Yoga), My Self sustains all beings without being attached to them.',
    'be': '৯.৪--৯.৫ শ্রী অভিনবগুপ্ত বলেছেন: সম্পূর্ণ জগৎ আমার অব্যক্ত রূপ থেকে ব্যাপ্ত, সব ভূত আমাতে স্থিত কিন্তু আমি তাদের মধ্যে আশ্রিত রূপে স্থিত নই; আর না ই ভূত আমাতে ভৌতিক রূপে স্থিত—এটা আমার ঐশ্বর্য যোগ, যা ভূতগুলোর ধারণ-পোষণকারী আত্মা হয়েও ভূতগুলোতে লিপ্ত হয় না।',
    'ka': '೯.೪--೯.೫ ಶ್ರೀ ಅಭಿನವಗುಪ್ತರು ಹೇಳುತ್ತಾರೆ: ಸಂಪೂರ್ಣ ಜಗತ್ತು ನನ್ನ ಅವ್ಯಕ್ತಸ್ವರೂಪದಿಂದ ವ್ಯಾಪ್ತವಾಗಿದೆ, ಸರ್ವಭೂತಗಳೂ ನನ್ನಲ್ಲಿಸಿವೆ ಆದರೆ ನಾನು ಅವುಗಳಲ್ಲಿ ಆಶ್ರಿತರೂಪದಲ್ಲಿದ್ದಿಲ್ಲ; ಹಾಗೂ ಭೂತಗಳೂ ನನ್ನಲ್ಲಿ ಭೌತಿಕವಾಗಿ ಸ್ಥಿತವಾಗಿಲ್ಲ—ಇದು ನನ್ನ ಐಶ್ವರ್ಯಯೋಗವಾಗಿದೆ, ಭೂತಗಳನ್ನು ಧಾರಣೆ-ಪೋಷಣೆ ಮಾಡುವ ಆತ್ಮನಾಗಿದ್ದರೂ ಭೂತಗಳಲ್ಲಿ ಲಿಪ್ತನಾಗುವುದಿಲ್ಲ'
}

madhav_4_5 = {
    'hi': '।।9.4--9.5।। श्री मध्वाचार्य कहते हैं: "मया ततमिदम्"—सर्वव्यापी विष्णु समस्त जगत् के नियन्ता हैं; जगत् प्रभु के अधीन है किंतु प्रभु जगत् के अधीन नहीं हैं। यही भगवान् का अलौकिक योग-ऐश्वर्य है।',
    'en': '9.4--9.5 Sri Madhavacharya states: "All this is pervaded by Me"—all-pervading Vishnu is the Supreme Ruler of the cosmos; the universe depends on the Lord, but the Lord is independent. Such is His divine sovereign majesty.',
    'be': '৯.৪--৯.৫ শ্রী মধ্বাচার্য বলেছেন: "ময়া ততমিদম্"—সর্বব্যাপী বিষ্ণু সমস্ত জগতের নিয়ন্তা; জগৎ প্রভুর অধীন কিন্তু প্রভু জগতের অধীন নন। এটাই ভগবানের অলৌকিক যোগ-ঐশ্বর্য।',
    'ka': '೯.೪--೯.೫ ಶ್ರೀ ಮಧ್ವಾಚಾರ್ಯರು ಹೇಳುತ್ತಾರೆ: "ಮಯಾ ತತಮಿದಮ್"—ಸರ್ವವ್ಯಾಪಿಯಾದ ವಿಷ್ಣುವು ಸಮಸ್ತ ಜಗತ್ತಿನ ನಿಯಂತೃವಾಗಿದ್ದಾನೆ; ಜಗತ್ತು ಪ್ರಭುವಿನ ಅಧೀನದಲ್ಲಿದೆ ಆದರೆ ಪ್ರಭುವು ಜಗತ್ತಿನ ಅಧೀನದಲ್ಲಿದ್ದಿಲ್ಲ. ಇದೇ ಭಗವಂತನ ಅಲೌಕಿಕ ಯೋಗೈಶ್ವರ್ಯವಾಗಿದೆ'
}

jaya_4_5 = {
    'hi': '।।9.4--9.5।। श्री जयतीर्थ कहते हैं: जगत् की भगवदधीनता और भगवान् की अनपेक्षता (स्वतंत्रता) का निरूपण है; सर्वधारयित्री सर्वेश्वर विष्णु की शक्ति अचिन्त्य है।',
    'en': '9.4--9.5 Sri Jayatirtha states: Demonstrating the cosmos\" dependence on God and the Lord\"s absolute independence; incomprehensible is the sustaining power of Supreme Lord Vishnu.',
    'be': '৯.৪--৯.৫ শ্রী জয়তীর্থ বলেছেন: জগতের ভগব অধীনতা এবং ভগবানের অনপেক্ষতা (স্বতন্ত্রতা) এর নিরুপণ; সর্বধারয়িত্রী সর্বেশ্বর বিষ্ণুর শক্তি অচিন্ত্য।',
    'ka': '೯.೪--೯.೫ ಶ್ರೀ ಜಯತೀರ್ಥರು ಹೇಳುತ್ತಾರೆ: ಜಗತ್ತಿನ ಭಗವದಧೀನತೆ ಹಾಗೂ ಭಗವಂತನ ಅನಪೇಕ್ಷತೆಯನ್ನು (ಸ್ವಾತಂತ್ರ್ಯ) ನಿರೂಪಿಸಲಾಗಿದೆ; ಸರ್ವಧಾರಯಿತ್ರಿಯಾದ ಸರ್ವೇಶ್ವರ ವಿಷ್ಣುವಿನ ಶಕ್ತಿಯು ಅಚಿಂತ್ಯವಾಗಿದೆ'
}

